#include <cstdint>
#include <iostream>
#include <map>
#include <string>

class Reassembler
{
public:
    explicit Reassembler(std::uint32_t firstSeq) : m_next{firstSeq} {}
    void add(std::uint32_t seq, const std::string& data) {}
    const std::string& stream() const { return m_stream; }

private:
    std::uint32_t m_next;
    std::map<std::uint32_t, std::string> m_waiting{};
    std::string m_stream{};
};

int main()
{
    Reassembler r{1000};
    r.add(1006, "World");
    r.add(1000, "Hello ");
    std::cout << r.stream() << '\n';
}
